import { mkdtemp, readFile, rename, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { type DocsScriptOptions, pdfScrubProducerPy } from "@snapotter/doc-engine";

function isAbortError(err: unknown): boolean {
  if (err === "timeout") return true;
  if (err instanceof Error) {
    if (err.name === "AbortError") return true;
    const code = (err as { code?: unknown }).code;
    if (code === "ABORT_ERR" || code === "canceled") return true;
  }
  return false;
}

/**
 * Tools whose PDF output is GENERATED by a conversion engine that stamps its
 * own name into the Producer/Creator metadata (LibreOffice, Ghostscript,
 * pdfcpu, WeasyPrint, PDFKit, the OCR pipeline). Their outputs get SnapOtter
 * stamped instead; see scrubPdfProducer.
 *
 * Deliberately excluded: tools that edit the user's own PDF and preserve its
 * metadata (merge/split/rotate/protect/unlock/repair/linearize via qpdf,
 * sign-pdf and flatten-pdf via PyMuPDF incremental edits), pdfa-convert,
 * where rewriting metadata after conversion risks PDF/A conformance, and
 * compress-pdf (plus its compress-pdf-to-N presets), which scrubs its own
 * Ghostscript candidates inside processV2 before measuring targetMet and
 * applying the never-enlarge fallback (#1373).
 */
export const SCRUB_PDF_PRODUCER_TOOLS: ReadonlySet<string> = new Set([
  // LibreOffice conversions
  "convert-document",
  "convert-presentation",
  "convert-spreadsheet",
  "word-to-pdf",
  "excel-to-pdf",
  "powerpoint-to-pdf",
  // WeasyPrint
  "html-to-pdf",
  "markdown-to-pdf",
  // pandoc/WeasyPrint chains
  "epub-convert",
  // Ghostscript rewrites (compress-pdf and its presets scrub inside
  // compress-pdf.ts before measuring targetMet and never-enlarge; #1373)
  "grayscale-pdf",
  // pdfcpu layout tools (pdfcpu stamps itself on every write)
  "crop-pdf",
  "nup-pdf",
  "booklet-pdf",
  "watermark-pdf",
  "pdf-page-numbers",
  // OCR produces a new searchable PDF
  "ocr-pdf",
  // PDFKit image-to-PDF family
  "image-to-pdf",
  "jpg-to-pdf",
  "png-to-pdf",
  "heic-to-pdf",
  "tiff-to-pdf",
  "webp-to-pdf",
  "gif-to-pdf",
  "eps-to-pdf",
]);

/**
 * In-place variant of scrubPdfProducer for tools that work on scratch files
 * and need the post-scrub byte size before making targetMet or never-enlarge
 * decisions (#1373). Writes to a sibling temp path and atomically renames over
 * filePath; any failure leaves filePath untouched.
 */
export async function scrubPdfProducerFile(
  filePath: string,
  opts?: DocsScriptOptions,
): Promise<void> {
  opts?.signal?.throwIfAborted();
  const outPath = `${filePath}.scrub.pdf`;
  try {
    await pdfScrubProducerPy(filePath, outPath, ...(opts ? [opts] : []));
    await rename(outPath, filePath);
  } catch (err) {
    await rm(outPath, { force: true }).catch(() => {});
    if (isAbortError(err)) throw err;
    opts?.signal?.throwIfAborted();
    console.warn(
      `[pdf-scrub] keeping original metadata: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

/**
 * Replace the conversion engine's Producer/Creator metadata with SnapOtter.
 * Best effort by design: any failure (missing PyMuPDF, malformed PDF,
 * dispatcher down) returns the original buffer unchanged so a cosmetic
 * metadata pass can never fail a job.
 */
export async function scrubPdfProducer(buffer: Buffer, opts?: DocsScriptOptions): Promise<Buffer> {
  opts?.signal?.throwIfAborted();
  let dir: string | null = null;
  try {
    dir = await mkdtemp(join(tmpdir(), "pdf-scrub-"));
    const inPath = join(dir, "in.pdf");
    const outPath = join(dir, "out.pdf");
    await writeFile(inPath, buffer);
    await pdfScrubProducerPy(inPath, outPath, ...(opts ? [opts] : []));
    return await readFile(outPath);
  } catch (err) {
    if (isAbortError(err)) throw err;
    opts?.signal?.throwIfAborted();
    console.warn(
      `[pdf-scrub] keeping original metadata: ${err instanceof Error ? err.message : String(err)}`,
    );
    return buffer;
  } finally {
    if (dir) await rm(dir, { recursive: true, force: true }).catch(() => {});
  }
}
